struct node_ops { long (*size)(const struct node *self); void (*destroy)(struct node *self); };
struct node { const struct node_ops *ops; };               /* Component */
struct dir  { struct node base; struct node **children; size_t n, cap; };
static long dir_size(const struct node *self) {
    const struct dir *d = (const struct dir *)self;       /* unchecked downcast */
    long total = 0;
    for (size_t i = 0; i < d->n; i++) total += d->children[i]->ops->size(d->children[i]);
    return total;
}
